pub struct Puzzle {
    pub id: &'static str,
    /// Mate in `mate` moves, or 0 for a fixed winning `line`.
    pub mate: i32,
    pub fen: &'static str,
    pub line: &'static [&'static str],
    pub theme: &'static str,
}

const fn mate(id: &'static str, n: i32, fen: &'static str) -> Puzzle {
    Puzzle { id, mate: n, fen, line: &[], theme: "" }
}
const fn line(id: &'static str, fen: &'static str, line: &'static [&'static str], theme: &'static str) -> Puzzle {
    Puzzle { id, mate: 0, fen, line, theme }
}

